 validateArtifactDigest,validateBaseline,validateCheckSchemas,validateCheckStateful,validateCommandOutcome,validateComparisonDocument,validateDependencyGraph,validateGitObjectId,validateNpmCiArgs,validateNpmCiArtifact,validateNpmCiResult,validateNpmVersionResult,verifyManifest,writePartialManifest
