function withTemp(action){const root=fs.mkdtempSync(path.join(os.tmpdir(),'janus-ci-evidence-test-'));try{return action(root);}finally{fs.rmSync(root,{recursive:true,force:true});assert.equal(fs.existsSync(root),false);}}
async function withTempAsync(action){const root=fs.mkdtempSync(path.join(os.tmpdir(),'janus-ci-evidence-test-'));try{return await action(root);}finally{fs.rmSync(root,{recursive:true,force:true});assert.equal(fs.existsSync(root),false);}}
function tap(count,changes=[]){const lines=['TAP version 13'];for(let i=1;i<=count;i++)lines.push(`# Subtest: case-${i}`,`ok ${i} - case-${i}`);lines.push(`1..${count}`,`# tests ${count}`,`# pass ${count}`,'# fail 0','# cancelled 0','# skipped 0','# todo 0','# duration_ms 1');for(const[find,replacement]of changes){const index=lines.indexOf(find);if(index>=0)lines[index]=replacement;else lines.push(replacement);}return lines.join('\n')+'\n';}
function baseline(expected={statefully_complete_requirements:35}){const stateful=expected.statefully_complete_requirements,structural=20,total=structural+stateful;return{baseline_classification:'EXPECTED_INCOMPLETE',catalog_id:'JN-CORE-LITE-0_2-REQUIREMENTS-001',core_commit:'8aae702a1bb11032f86a8a32e164e3a68fc961da',core_sha256:'709279f32abe18d792c68299b080c349e1ed0c45780775581aacf32484e78b0b',atomic_requirements_total:156,structurally_complete_requirements:structural,statefully_complete_requirements:stateful,requirement_complete_total:total,schema_projection_covered_requirements:10,stateful_projection_covered_requirements:7,derived_not_implemented_requirements:156-total-17,technical_verdict:'NOT_EVALUATED',conformance_claimed:false};}
function tapSummary(count=1){return{plan:count,counts:{tests:count,pass:count,fail:0,cancelled:0,skipped:0,todo:0},tests:Array.from({length:count},(_,index)=>({status:'ok',ordinal:index+1,name:`case-${index+1}`}))};}
function npmLsValue(rootPath){return{name:'janus-core-conformance',version:'0.0.0',...(rootPath?{path:rootPath}:{}),dependencies:{ajv:{version:'8.20.0',resolved:'https://registry.npmjs.org/ajv',dependencies:{'fast-deep-equal':{version:'3.1.3'},'fast-uri':{version:'3.1.9'},'json-schema-traverse':{version:'1.0.0'},'require-from-string':{version:'2.0.2'}}}}};}
function dependencyArchive(root,{versions={},scripts={}}={}){const base=path.join(root,'tools/core-conformance'),packages={ajv:'8.20.0','fast-deep-equal':'3.1.3','fast-uri':'3.1.9','json-schema-traverse':'1.0.0','require-from-string':'2.0.2'};fs.mkdirSync(base,{recursive:true});fs.writeFileSync(path.join(base,'package-lock.json'),JSON.stringify({lockfileVersion:3}));for(const[name,version]of Object.entries(packages)){const dir=path.join(base,'node_modules',name);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'package.json'),JSON.stringify({name,version:versions[name]||version,...(scripts[name]?{scripts:scripts[name]}:{})}));}}
function envelope(paths=CI_MAINTENANCE_PATHS){const ordered=[...paths].sort((a,b)=>Buffer.from(a).compare(Buffer.from(b))),raw=Buffer.concat(ordered.flatMap(value=>[Buffer.from(value),Buffer.from([0])]));return{schema_version:'janus-ci-change-envelope-v2',profile:classifyChangedPaths(paths),parent:'a'.repeat(40),commit:'b'.repeat(40),changed_path_count:ordered.length,changed_paths_sha256:sha256(raw),changed_paths:ordered};}
function unboundSummary(replica,paths=CI_MAINTENANCE_PATHS){const changeEnvelope=envelope(paths),expected=expectedResultsForEnvelope(changeEnvelope),commandResults=Object.fromEntries(commandIds.slice(5).map(id=>[id,{exit:id==='run'?1:0,signal:null,timeout:false}]));return{schema_version:'janus-ci-gate2-replica-summary-v2',status:'PASS_NOT_CONFORMANCE',replica_id:replica,run_id:'44365947637',run_attempt:1,change_envelope:changeEnvelope,commit:'b'.repeat(40),tree:'c'.repeat(40),hashes:{workflow:digest,runner:digest,test:digest,integration_module:digest,integration_test:digest,package:digest,lock:digest},lockfile_version:3,package_versions:{ajv:'8.20.0','fast-deep-equal':'3.1.3','fast-uri':'3.1.9','json-schema-traverse':'1.0.0','require-from-string':'2.0.2'},dependency_graph:{ajv:'8.20.0','fast-deep-equal':'3.1.3','fast-uri':'3.1.9','json-schema-traverse':'1.0.0','require-from-string':'2.0.2'},runner_metadata:{image_os:'ubuntu24',image_version:'20261101.1',node_version:'v24.13.1',npm_version:'11.8.0',runner_arch:'X64',runner_environment:'github-hosted',runner_name:`runner-${replica}`,runner_os:'Linux'},timestamps:{started_utc:'2026-11-09T00:00:00Z',ended_utc:'2026-11-09T00:01:00Z'},paths:{work_root:'RUNNER_TEMP_TASK_SPECIFIC',evidence:'RUNNER_TEMP_EVIDENCE'},command_results:commandResults,normalized_results:{'check-schemas':{classification:'SCHEMA_FOUNDATION_PASS_NOT_CONFORMANCE',schema_count:6,fixture_count:42,all_results_pass:true,conformance_claimed:false},'schema-foundation':tapSummary(expected.tap['schema-foundation']),'schema-content-binding':tapSummary(expected.tap['schema-content-binding']),'e-minus-evaluator':tapSummary(expected.tap['e-minus-evaluator']),'e-minus-schema-binding-integration':tapSummary(expected.tap['e-minus-schema-binding-integration']),'stateful-history-reference':tapSummary(expected.tap['stateful-history-reference']),baseline:tapSummary(expected.tap.baseline),'check-stateful':{classification:'STATEFUL_HISTORY_REFERENCE_FOUNDATION',scenario_count:expected.scenario_count,scenario_runs_passed:expected.scenario_count,stateful_complete_requirements:expected.statefully_complete_requirements,stateful_projection_requirements:7,technical_verdict:'NOT_EVALUATED',conformance_claimed:false},run:baseline(expected)},deterministic_outputs:{'check-schemas':digest,'check-stateful':digest,run:digest},checkout_clean:true};}
function governedJsonRaw(id,value){if(id==='check-schemas'){const result=value.normalized_results[id];return Buffer.from(JSON.stringify({classification:result.classification,schema_count:result.schema_count,fixture_count:result.fixture_count,conformance_claimed:false,results:Array.from({length:result.fixture_count},(_,index)=>({case_id:`C${index}`,result:'PASS'}))})+'\n');}if(id==='check-stateful'){const result=value.normalized_results[id];return Buffer.from(JSON.stringify({...result,results:Array.from({length:result.scenario_count},(_,index)=>({scenario_id:`S${index}`}))})+'\n');}if(id==='run')return Buffer.from(JSON.stringify(value.normalized_results.run)+'\n');throw new Error('NOT_GOVERNED_JSON');}
function summary(replica,paths=CI_MAINTENANCE_PATHS){const value=unboundSummary(replica,paths);for(const id of ['check-schemas','check-stateful','run'])value.deterministic_outputs[id]=sha256(governedJsonRaw(id,value));return value;}
function writeCommandEvidence(root,replica,id,summaryValue){const dir=path.join(root,'commands',id),npmCwd=`/tmp/${replica}/archive/tools/core-conformance`;fs.mkdirSync(dir,{recursive:true});let stdout=Buffer.from(`output-${id}`),args=['node',`/tmp/${replica}/${id}`],cwd=`/tmp/${replica}/archive`;if(tapIds.includes(id)){const count=summaryValue.normalized_results[id].plan;stdout=Buffer.from(tap(count,[[`# duration_ms 1`,`# duration_ms ${replica==='replica-1'?1:2}`]]));}if(['check-schemas','check-stateful','run'].includes(id))stdout=governedJsonRaw(id,summaryValue);if(id==='npm-ci'){stdout=Buffer.alloc(0);args=['npm','ci','--ignore-scripts','--no-audit','--no-fund','--update-notifier=false','--engine-strict','--loglevel=silent','--cache',`/tmp/${replica}/cache`,'--userconfig',`/tmp/${replica}/user.npmrc`,'--globalconfig',`/tmp/${replica}/global.npmrc`];cwd=npmCwd;}if(id==='npm-version'){stdout=Buffer.from('11.8.0\n');cwd=npmCwd;}if(id==='npm-ls'){stdout=Buffer.from(JSON.stringify(npmLsValue(npmCwd)));args=['npm','ls','--all','--json','--cache',`/tmp/${replica}/cache`,'--userconfig',`/tmp/${replica}/user.npmrc`,'--globalconfig',`/tmp/${replica}/global.npmrc`];cwd=npmCwd;}const stderr=Buffer.alloc(0);fs.writeFileSync(path.join(dir,'command.json'),JSON.stringify({args,cwd}));fs.writeFileSync(path.join(dir,'stdout.raw'),stdout);fs.writeFileSync(path.join(dir,'stderr.raw'),stderr);fs.writeFileSync(path.join(dir,'result.json'),JSON.stringify({exit:id==='run'?1:0,signal:null,timeout:false,output_limit:false,spawn_error:null,expected_exit:id==='run'?1:0,started_utc:'2026-11-09T00:00:00Z',ended_utc:'2026-11-09T00:00:01Z',stdout:{bytes:stdout.length,sha256:sha256(stdout)},stderr:{bytes:0,sha256:sha256(stderr)}}));return stdout;}
function evidence(root,replica,paths=CI_MAINTENANCE_PATHS){fs.mkdirSync(root,{recursive:true});const value=summary(replica,paths);for(const id of commandIds){const stdout=writeCommandEvidence(root,replica,id,value);if(['check-schemas','check-stateful','run'].includes(id))value.deterministic_outputs[id]=sha256(stdout);}writePartialManifest(root);fs.writeFileSync(path.join(root,'summary.json'),JSON.stringify(value));finalizeManifest(root);}
function remanifest(root){const summaryFile=path.join(root,'summary.json'),raw=fs.readFileSync(summaryFile);fs.rmSync(summaryFile);writePartialManifest(root);fs.writeFileSync(summaryFile,raw);finalizeManifest(root);}
function replaceSummary(root,value){fs.writeFileSync(path.join(root,'summary.json'),JSON.stringify(value));finalizeManifest(root);}
function mutateStream(root,id,stream,raw,{bind=true}={}){const dir=path.join(root,'commands',id),file=path.join(dir,`${stream}.raw`),resultFile=path.join(dir,'result.json'),result=JSON.parse(fs.readFileSync(resultFile));fs.writeFileSync(file,raw);if(bind){result[stream]={bytes:raw.length,sha256:sha256(raw)};fs.writeFileSync(resultFile,JSON.stringify(result));}remanifest(root);}
function git(root,...args){const result=spawnSync('git',args,{cwd:root,encoding:null});assert.equal(result.status,0,Buffer.from(result.stderr||'').toString());return Buffer.from(result.stdout||'');}
function envelopeRepo(root,changedPaths=CI_MAINTENANCE_PATHS){fs.mkdirSync(root,{recursive:true});const repo=path.join(root,'repo'),runner=path.join(root,'runner');fs.mkdirSync(repo);fs.mkdirSync(runner);git(repo,'init','-q');git(repo,'config','user.name','Test');git(repo,'config','user.email','test@example.invalid');for(const relative of changedPaths){const file=path.join(repo,...relative.split('/'));fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,'base\n');}git(repo,'add','.');git(repo,'commit','-q','-m','base');const branch=git(repo,'rev-parse','--abbrev-ref','HEAD').toString().trim(),before=git(repo,'rev-parse','HEAD').toString().trim();for(const relative of changedPaths)fs.appendFileSync(path.join(repo,...relative.split('/')),'changed\n');git(repo,'add','.');git(repo,'commit','-q','-m','change');const after=git(repo,'rev-parse','HEAD').toString().trim(),observed=git(repo,'diff','--no-renames','--name-only','-z',before,after,'--'),observedFile=path.join(runner,'changed-paths.bin');fs.writeFileSync(observedFile,observed);return{repo,runner,branch,before,after,observed,observedFile,args:{source:repo,observedPathsFile:observedFile,runnerTemp:runner,eventName:'push',ref:'refs/heads/codex/gate-2-conformance-contract',runAttempt:'1',runId:'44365947637',before,after,githubSha:after}};}

test('strict TAP accepts the exact plan counts and ordered results',()=>{const value=parseTap(Buffer.from(tap(3)),3);assert.equal(value.counts.pass,3);assert.deepEqual(value.tests.map(x=>x.name),['case-1','case-2','case-3']);});
test('truncated TAP is rejected',()=>errorCode(()=>parseTap(Buffer.from('TAP version 13\nok 1 - x\n'),1),'TAP_PLAN'));
test('missing final plan is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1).replace('1..1\n','')),1),'TAP_PLAN'));
test('not ok is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['ok 1 - case-1','not ok 1 - case-1']])),1),'TAP_NOT_OK'));
test('missing summary count is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1).replace('# tests 1\n','')),1),'TAP_COUNT_FIELD'));
test('duplicate summary count is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1)+ '# tests 1\n'),1),'TAP_COUNT_FIELD'));
test('inconsistent pass count is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# pass 1','# pass 0']])),1),'TAP_COUNTS'));
test('nonzero skipped is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# skipped 0','# skipped 1']])),1),'TAP_COUNTS'));
test('nonzero todo is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# todo 0','# todo 1']])),1),'TAP_COUNTS'));
test('nonzero cancelled is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# cancelled 0','# cancelled 1']])),1),'TAP_COUNTS'));
