test('NUL path parsing is fatal, canonical, duplicate-free and bytewise deterministic',()=>{const a=parseChangedPathStream(Buffer.from('tools/core-conformance/ci-gate2-evidence.mjs\0.github/workflows/gate-2-evidence.yml\0tools/core-conformance/test/ci-gate2-evidence.test.mjs\0')),b=parseChangedPathStream(Buffer.from('.github/workflows/gate-2-evidence.yml\0tools/core-conformance/test/ci-gate2-evidence.test.mjs\0tools/core-conformance/ci-gate2-evidence.mjs\0'));assert.deepEqual(a.ordered,b.ordered);assert.equal(a.digest,b.digest);for(const raw of [Buffer.alloc(0),Buffer.alloc(64*1024+1,97),Buffer.from('x'),Buffer.from('x\0x\0'),Buffer.from('/x\0'),Buffer.from('a\\b\0'),Buffer.from('a/../b\0'),Buffer.from('a/./b\0'),Buffer.from('a//b\0'),Buffer.from('a\nb\0'),Buffer.from('a\rb\0'),Buffer.from('a\tb\0'),Buffer.from([0xc2,0x80,0]),Buffer.from([0xff,0])])assert.throws(()=>parseChangedPathStream(raw),CIEvidenceError);});
