test('dependency graph still rejects incomplete and additional graphs',()=>withTemp(root=>{dependencyArchive(root);const incomplete=npmLsValue();delete incomplete.dependencies.ajv.dependencies['fast-uri'];errorCode(()=>validateDependencyGraph(root,incomplete),'DEPENDENCY_GRAPH');const additional=npmLsValue();additional.dependencies.ajv.dependencies.unexpected={version:'1.0.0'};errorCode(()=>validateDependencyGraph(root,additional),'DEPENDENCY_GRAPH');}));
test('npm ci artifact rejects missing raw and invalid binding',()=>withTemp(root=>{evidence(root,'replica-1');fs.rmSync(path.join(root,'commands/npm-ci/stdout.raw'));errorCode(()=>validateNpmCiArtifact(root),'NPM_CI_RAW_MISSING');}));
test('npm ci artifact rejects manipulated stream binding',()=>withTemp(root=>{evidence(root,'replica-1');const file=path.join(root,'commands/npm-ci/result.json'),value=JSON.parse(fs.readFileSync(file));value.stdout.sha256=digest;fs.writeFileSync(file,JSON.stringify(value));errorCode(()=>validateNpmCiArtifact(root),'NPM_CI_STREAM_BINDING_INVALID');}));
test('nonzero silent npm failure records raw streams, result and partial manifest fail-closed',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');const args=[process.execPath,'-e','process.stdout.write("out");process.stderr.write("err");process.exit(7)','--','--loglevel=silent'];await rejectCode(()=>runRecordedCommand({id:'npm-ci-silent-failure',args,cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000,outcomeErrorCode:'NPM_CI_OUTCOME_INVALID'}),'NPM_CI_OUTCOME_INVALID');const dir=path.join(root,'commands/npm-ci-silent-failure');assert.equal(fs.readFileSync(path.join(dir,'stdout.raw'),'utf8'),'out');assert.equal(fs.readFileSync(path.join(dir,'stderr.raw'),'utf8'),'err');const result=JSON.parse(fs.readFileSync(path.join(dir,'result.json')));assert.equal(result.exit,7);assert.equal(result.expected_exit,0);assert.equal(result.signal,null);assert.equal(result.timeout,false);assert.equal(result.output_limit,false);assert.equal(result.spawn_error,null);const partial=JSON.parse(fs.readFileSync(path.join(root,'manifest.partial.json')));assert.equal(partial.status,'PARTIAL');assert.ok(partial.entries.some(entry=>entry.relative_path==='commands/npm-ci-silent-failure/stdout.raw'));}));
test('comparator rejects identical nonempty npm stdout in both artifacts',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right])mutateStream(item,'npm-ci','stdout',Buffer.from('same'));errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_STDOUT_NONEMPTY');}));
test('comparator rejects identical nonempty npm stderr in both artifacts',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right])mutateStream(item,'npm-ci','stderr',Buffer.from('same'));errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_STDERR_NONEMPTY');}));
test('comparator rejects identical invalid npm outcomes',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){const file=path.join(item,'commands/npm-ci/result.json'),value=JSON.parse(fs.readFileSync(file));value.exit=1;fs.writeFileSync(file,JSON.stringify(value));remanifest(item);}errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_OUTCOME_INVALID');}));
test('comparator rejects identical missing npm raw files',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){fs.rmSync(path.join(item,'commands/npm-ci/stdout.raw'));remanifest(item);}errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_RAW_MISSING');}));
test('comparator rejects identical manipulated npm hashes',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){const file=path.join(item,'commands/npm-ci/result.json'),value=JSON.parse(fs.readFileSync(file));value.stdout.sha256=digest;fs.writeFileSync(file,JSON.stringify(value));remanifest(item);}errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_STREAM_BINDING_INVALID');}));
test('comparator rejects identical unknown npm result fields',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){const file=path.join(item,'commands/npm-ci/result.json'),value=JSON.parse(fs.readFileSync(file));value.unknown=true;fs.writeFileSync(file,JSON.stringify(value));remanifest(item);}errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_CI_OUTCOME_INVALID');}));
test('comparator rejects two identically partial remanifested artifacts',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){fs.rmSync(path.join(item,'commands/run'),{recursive:true});remanifest(item);}errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'ARTIFACT_COMMAND_MISSING');}));
test('npm version is one semantic version with empty stderr',()=>{const base={exit:0,signal:null,timeout:false,output_limit:false,spawn_error:null,stderr:Buffer.alloc(0)};assert.equal(validateNpmVersionResult({...base,stdout:Buffer.from('11.8.0\n')}),'11.8.0');errorCode(()=>validateNpmVersionResult({...base,stdout:Buffer.from('not-version\n')}),'NPM_VERSION_INVALID');errorCode(()=>validateNpmVersionResult({...base,stdout:Buffer.from('1.2.3\n2.0.0\n')}),'NPM_VERSION_INVALID');});
test('npm ls normalizes an exact expected root path and rejects unknown/problem fields',()=>{const expected='/tmp/exact-root',one=normalizeNpmLs(Buffer.from(JSON.stringify(npmLsValue(expected))),expected),two=normalizeNpmLs(Buffer.from(JSON.stringify(npmLsValue(expected))),expected);assert.deepEqual(one,two);const unknown=npmLsValue('/tmp/x');unknown.unknown=true;errorCode(()=>normalizeNpmLs(Buffer.from(JSON.stringify(unknown)),'/tmp/x'),'NPM_LS_ROOT');const missing=npmLsValue('/tmp/x');missing.dependencies.ajv.missing=true;errorCode(()=>normalizeNpmLs(Buffer.from(JSON.stringify(missing)),'/tmp/x'),'NPM_LS_PROBLEM');});
test('npm ls rejects relative and mismatched expected root paths',()=>{errorCode(()=>normalizeNpmLs(Buffer.from(JSON.stringify(npmLsValue('relative/root'))),'/tmp/root'),'NPM_LS_ROOT_PATH');errorCode(()=>normalizeNpmLs(Buffer.from(JSON.stringify(npmLsValue('/tmp/root'))),'relative/root'),'NPM_LS_ROOT_PATH');errorCode(()=>normalizeNpmLs(Buffer.from(JSON.stringify(npmLsValue('/tmp/other'))),'/tmp/root'),'NPM_LS_ROOT_PATH');});
test('comparator rejects the same incorrect npm root path in both replicas',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right])mutateStream(item,'npm-ls','stdout',Buffer.from(JSON.stringify(npmLsValue('/tmp/incorrect'))));errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'NPM_LS_ROOT_PATH');}));
test('bounded sync subprocess rejects timeout',()=>withTemp(root=>errorCode(()=>runSyncBounded({command:process.execPath,args:['-e','setTimeout(()=>{},10000)'],cwd:root,timeoutMs:20}),'SYNC_TIMEOUT')));
test('bounded sync subprocess rejects maxBuffer overflow',()=>withTemp(root=>errorCode(()=>runSyncBounded({command:process.execPath,args:['-e','process.stdout.write("x".repeat(4096))'],cwd:root,maxBuffer:32}),'SYNC_MAX_BUFFER')));
test('bounded sync subprocess rejects execution error',()=>withTemp(root=>errorCode(()=>runSyncBounded({command:path.join(root,'missing'),args:[],cwd:root}),'SYNC_EXEC_ERROR')));
test('bounded sync subprocess rejects signal and null status',()=>withTemp(root=>errorCode(()=>runSyncBounded({command:process.execPath,args:['-e','process.kill(process.pid,"SIGTERM")'],cwd:root}),'SYNC_SIGNAL')));
test('bounded sync subprocess rejects unexpected stderr',()=>withTemp(root=>errorCode(()=>runSyncBounded({command:process.execPath,args:['-e','process.stderr.write("x")'],cwd:root}),'SYNC_STDERR')));
test('async stdout limit preserves bounded raw result and partial manifest',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');await rejectCode(()=>runRecordedCommand({id:'stdout-limit',args:[process.execPath,'-e','process.stdout.write("x".repeat(4096))'],cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000,maxOutputBytes:32}),'COMMAND_OUTPUT_LIMIT');assert.equal(fs.readFileSync(path.join(root,'commands/stdout-limit/stdout.raw')).length,32);const value=JSON.parse(fs.readFileSync(path.join(root,'commands/stdout-limit/result.json')));assert.equal(value.output_limit,true);assert.equal(fs.existsSync(path.join(root,'manifest.partial.json')),true);}));
test('async stderr limit preserves bounded raw result and partial manifest',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');await rejectCode(()=>runRecordedCommand({id:'stderr-limit',args:[process.execPath,'-e','process.stderr.write("x".repeat(4096))'],cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000,maxOutputBytes:32}),'COMMAND_OUTPUT_LIMIT');assert.equal(fs.readFileSync(path.join(root,'commands/stderr-limit/stderr.raw')).length,32);const value=JSON.parse(fs.readFileSync(path.join(root,'commands/stderr-limit/result.json')));assert.equal(value.output_limit,true);}));
test('async output limit terminates the child process group',async()=>withTempAsync(async root=>{const marker=path.join(root,'descendant-marker'),child=`setTimeout(()=>require('node:fs').writeFileSync(${JSON.stringify(marker)},'bad'),250)`,parent=`require('node:child_process').spawn(process.execPath,['-e',${JSON.stringify(child)}],{stdio:'ignore'});process.stdout.write('x'.repeat(4096));setTimeout(()=>{},10000)`;writePartialManifest(root,'INITIAL');await rejectCode(()=>runRecordedCommand({id:'group-limit',args:[process.execPath,'-e',parent],cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000,maxOutputBytes:32}),'COMMAND_OUTPUT_LIMIT');await new Promise(resolve=>setTimeout(resolve,400));assert.equal(fs.existsSync(marker),false);}));
test('protected cleanup accepts only a task root with exact sentinel',()=>withTemp(root=>{const runner=path.join(root,'runner'),source=path.join(root,'source'),evidenceDir=path.join(root,'evidence'),work=path.join(runner,'task');for(const dir of [runner,source,evidenceDir])fs.mkdirSync(dir);const guard=prepareWorkRoot({runnerTemp:runner,workRoot:work,source,evidence:evidenceDir});assert.equal(cleanupWorkRoot(guard),true);assert.equal(fs.existsSync(work),false);}));
test('protected cleanup rejects unsafe roots and overlaps',()=>withTemp(root=>{const runner=path.join(root,'runner'),source=path.join(root,'source'),evidenceDir=path.join(root,'evidence'),external=path.join(root,'external');for(const dir of [runner,source,evidenceDir,external])fs.mkdirSync(dir);for(const work of ['/',runner,external,source,evidenceDir])errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:work,source,evidence:evidenceDir}),'WORK_ROOT_UNSAFE');const nestedSource=path.join(runner,'source'),nestedEvidence=path.join(runner,'evidence');fs.mkdirSync(nestedSource);fs.mkdirSync(nestedEvidence);errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:nestedSource,source:nestedSource,evidence:nestedEvidence}),'WORK_ROOT_OVERLAP');errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:nestedEvidence,source:nestedSource,evidence:nestedEvidence}),'WORK_ROOT_OVERLAP');}));
test('protected cleanup rejects missing or incorrect sentinel without deleting',()=>withTemp(root=>{for(const mode of ['missing','incorrect']){const runner=path.join(root,`runner-${mode}`),source=path.join(root,`source-${mode}`),evidenceDir=path.join(root,`evidence-${mode}`),work=path.join(runner,'task');for(const dir of [runner,source,evidenceDir])fs.mkdirSync(dir);const guard=prepareWorkRoot({runnerTemp:runner,workRoot:work,source,evidence:evidenceDir});if(mode==='missing')fs.rmSync(guard.sentinel);else fs.writeFileSync(guard.sentinel,'{}');errorCode(()=>cleanupWorkRoot(guard),'WORK_ROOT_SENTINEL');assert.equal(fs.existsSync(work),true);}}));
test('protected work root rejects symlink resolution outside RUNNER_TEMP',()=>withTemp(root=>{const runner=path.join(root,'runner'),source=path.join(root,'source'),evidenceDir=path.join(root,'evidence'),external=path.join(root,'external');for(const dir of [runner,source,evidenceDir,external])fs.mkdirSync(dir);fs.symlinkSync(external,path.join(runner,'escape'));errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:path.join(runner,'escape','task'),source,evidence:evidenceDir}),'WORK_ROOT_UNSAFE');}));
test('protected work root rejects ancestors and descendants of protected paths',()=>withTemp(root=>{const runner=path.join(root,'runner'),container=path.join(runner,'container'),source=path.join(container,'source'),evidenceDir=path.join(runner,'evidence');for(const dir of [runner,container,source,evidenceDir])if(!fs.existsSync(dir))fs.mkdirSync(dir);errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:path.join(source,'child'),source,evidence:evidenceDir}),'WORK_ROOT_OVERLAP');errorCode(()=>prepareWorkRoot({runnerTemp:runner,workRoot:container,source,evidence:evidenceDir}),'WORK_ROOT_OVERLAP');}));
test('protected cleanup rejects a symlinked sentinel without deleting',()=>withTemp(root=>{const runner=path.join(root,'runner'),source=path.join(root,'source'),evidenceDir=path.join(root,'evidence'),work=path.join(runner,'task'),outside=path.join(root,'outside');for(const dir of [runner,source,evidenceDir])fs.mkdirSync(dir);fs.writeFileSync(outside,'{}');const guard=prepareWorkRoot({runnerTemp:runner,workRoot:work,source,evidence:evidenceDir});fs.rmSync(guard.sentinel);fs.symlinkSync(outside,guard.sentinel);errorCode(()=>cleanupWorkRoot(guard),'WORK_ROOT_SENTINEL');assert.equal(fs.existsSync(work),true);}));
